package com.oyuki.marketsquare.entity; import com.oyuki.user.entity.User; import com.oyuki.marketsquare.enums.AgentStatus; import jakarta.persistence.*; import lombok.*; import java.math.BigDecimal; @Entity @Table(name="market_agents") @Getter @Setter @NoArgsConstructor @AllArgsConstructor @Builder public class MarketAgentProfile { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @OneToOne(optional=false) @JoinColumn(name="user_id",unique=true) private User user; @ManyToOne @JoinColumn(name="assigned_lga_id") private LocalGovernment assignedLga; @ManyToOne @JoinColumn(name="assigned_market_id") private Market assignedMarket; private String idDocumentUrl; private String emergencyContactName; private String emergencyContactPhone; private String bankName; private String accountName; private String accountNumber; @Enumerated(EnumType.STRING) @Builder.Default private AgentStatus status=AgentStatus.PENDING; @Builder.Default private BigDecimal performanceRating=BigDecimal.ZERO; @Enumerated(EnumType.STRING) @Column(name="commission_type") private com.oyuki.marketsquare.enums.CommissionType commissionType; private BigDecimal commissionValue; }